// SectionLabel, AS GRAPH SOURCE (#3680, epic #3604) — a structural shared/ui layout primitive authored as DATA.
// `provides: "@/shared/ui/layout/SectionLabel"` makes the runtime loader vendor THIS over the bundled module (registered code
// is the fallback). Transcribed verbatim; deps stay registered code.
import type { CSSProperties, ReactNode } from "react";

export interface SectionLabelProps {
  children: ReactNode;
  /** `md` (default): 10px / .06em — the common section/kv label. `sm`: 9px / .08em — the tighter
   *  caption used in dense KPI/analytics tiles. A raw px number is also legal (dense .08em tracking) —
   *  e.g. `size={9.5}`, the legacy `.ulabel` size (#2420). */
  size?: "sm" | "md" | number;
  /** `dim` (default, var(--fg-dim)) or `muted` (var(--fg-muted)). */
  tone?: "dim" | "muted";
  /** Optional right-aligned slot (#2420) — renders a space-between label row (label · right), the
   *  repeated "section header with a trailing note/control" idiom. `style` then styles the ROW. */
  right?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

/** The uppercase mono micro-label — `fontFamily:var(--mono)` + `textTransform:uppercase` +
 *  letter-spacing + a dim/muted color — hand-rolled ~75× across the app. Collapses the four
 *  boilerplate style props into one primitive while keeping per-site spacing via `style` (#1837). */
export function SectionLabel({ children, size = "md", tone = "dim", right, className, style }: SectionLabelProps) {
  const label: CSSProperties = {
    fontSize: typeof size === "number" ? size : size === "sm" ? 9 : 10,
    letterSpacing: size === "md" ? ".06em" : ".08em",
    textTransform: "uppercase",
    color: tone === "muted" ? "var(--fg-muted)" : "var(--fg-dim)",
  };
  if (right == null) {
    return (
      <div className={`${className ?? ""} mono`} style={{ ...label, ...style }}>
        {children}
      </div>
    );
  }
  return (
    <div className={className} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, ...style }}>
      <div className="mono" style={label}>{children}</div>
      {right}
    </div>
  );
}

tests.src:
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import { SectionLabel } from "./SectionLabel";

describe("SectionLabel", () => {
  it("renders uppercase mono children with the dim tone by default", () => {
    render(<SectionLabel>Scopes requested</SectionLabel>);
    const el = screen.getByText("Scopes requested");
    expect(el.style.textTransform).toBe("uppercase");
    // The mono font-family now comes from the `mono` utility class, not an inline style.
    expect(el.classList.contains("mono")).toBe(true);
    expect(el.style.color).toBe("var(--fg-dim)");
  });

  it("honors size + tone presets and merges a style override", () => {
    render(<SectionLabel size="sm" tone="muted" style={{ marginBottom: 6 }}>What you get</SectionLabel>);
    const el = screen.getByText("What you get");
    expect(el.style.fontSize).toBe("9px");
    expect(el.style.color).toBe("var(--fg-muted)");
    expect(el.style.marginBottom).toBe("6px");
  });

  it("accepts a raw px size with the dense .08em tracking (#2420)", () => {
    render(<SectionLabel size={9.5}>staged files</SectionLabel>);
    const el = screen.getByText("staged files");
    expect(el.style.fontSize).toBe("9.5px");
    // CSSOM serializes the leading-dot value with its zero — assert the canonical form.
    expect(el.style.letterSpacing).toBe("0.08em");
    expect(el.classList.contains("mono")).toBe(true);
  });

  it("renders a space-between label row when `right` is set — style lands on the ROW (#2420)", () => {
    render(
      <SectionLabel size={9.5} right={<button>+ add</button>} style={{ marginBottom: 9 }}>
        Responsibilities
      </SectionLabel>,
    );
    const label = screen.getByText("Responsibilities");
    const row = label.parentElement as HTMLElement;
    // Label keeps the micro-label typography; the wrapper row carries the layout + spacing.
    expect(label.style.textTransform).toBe("uppercase");
    expect(label.style.fontSize).toBe("9.5px");
    expect(row.style.display).toBe("flex");
    expect(row.style.justifyContent).toBe("space-between");
    expect(row.style.marginBottom).toBe("9px");
    // The right slot renders inside the row.
    expect(screen.getByText("+ add").parentElement).toBe(row);
  });
});
